'use strict';
function thisAtob(str){ var base64 = Buffer.from(str, 'base64'); return base64.toString('binary'); }
exports.decodeAttachment = thisAtob;
// ---- a few hundred chars of unrelated library code so the decoder and the
// view compiler below are well outside the proximity window ----
function range(n){ var out = []; for (var i = 0; i < n; i++) { out.push(i * i + 1); } return out; }
function pad(s, n){ while (s.length < n) { s = ' ' + s; } return s; }
function merge(a, b){ var o = {}; for (var k in a) o[k] = a[k]; for (var k in b) o[k] = b[k]; return o; }
function pluck(rows, key){ return rows.map(function(r){ return r[key]; }); }
function sum(xs){ return xs.reduce(function(a, b){ return a + b; }, 0); }
function group(rows, key){ var g = {}; rows.forEach(function(r){ (g[r[key]] = g[r[key]] || []).push(r); }); return g; }
function compileView(mapSource){ return new Function('doc', 'emit', mapSource); }
exports.compileView = compileView;
